/**
 * A tiny first-in-first-out queue for toast calls made before the viewport exists. Base UI starts a toast's
 * auto-close timer when the toast is added, so a toast added while the (lazy) viewport is still loading could
 * expire unseen. `ToastProvider` holds calls in this queue until its `viewportReady` prop turns true.
 */
export type ToastQueue = {
  /** Hold one call until {@link ToastQueue.flush}. */
  push: (run: () => void) => void;
  /** Run every held call in the order it was pushed, then empty the queue. */
  flush: () => void;
  /** How many calls are waiting. */
  size: () => number;
};

/** Create an empty {@link ToastQueue}. */
export function createToastQueue(): ToastQueue {
  let held: (() => void)[] = [];
  return {
    push: (run) => {
      held.push(run);
    },
    flush: () => {
      const batch = held;
      held = [];
      for (const run of batch) run();
    },
    size: () => held.length,
  };
}

/** What `useToast` needs from a provider that may not have a viewport yet. */
export type ToastGate = {
  /** True once a viewport is mounted (always true for a provider that was not given `viewportReady`). */
  isReady: () => boolean;
  /** Ask the app to load its viewport now (called when a toast is held). */
  request: () => void;
  /** Hold a call until the gate opens. */
  hold: (run: () => void) => void;
  /** A fresh id for a toast that is held, so `add` can return it at once. */
  nextId: () => string;
  /** Called by the provider when its props change. Opening the gate runs the held calls in order. */
  sync: (ready: boolean, onNeeded: (() => void) | undefined) => void;
};

/** Create the gate a `ToastProvider` shares with `useToast`: it holds calls while the viewport is not ready. */
export function createToastGate(ready: boolean): ToastGate {
  const queue = createToastQueue();
  let open = ready;
  let needed: (() => void) | undefined;
  let counter = 0;
  return {
    isReady: () => open,
    request: () => needed?.(),
    hold: queue.push,
    nextId: () => `sheen-held-toast-${(counter += 1)}`,
    sync: (nextReady, onNeeded) => {
      open = nextReady;
      needed = onNeeded;
      if (open) queue.flush();
    },
  };
}

"use client";

import { createContext, useContext, useEffect, useMemo, useState, type ComponentProps, type ReactNode } from "react";
import { Toast as BaseToast } from "@base-ui/react/toast";

import { createToastGate, type ToastGate } from "./toast-gate";

const ToastGateContext = createContext<ToastGate | null>(null);

/**
 * Glass toasts that stack, expand on hover and can be swiped away. This is the provider: it owns the
 * queue of toasts. Put it once near the root of your app, with a single `Toaster` inside it, then call
 * `useToast()` anywhere below to show messages. Use toasts for short, non-blocking feedback ("Saved");
 * use `Dialog` or an inline message when the person must act.
 *
 * Keyboard: F6 moves focus to the toast viewport (Base UI; the region's name and a hidden line on every toast
 * with an action say so once, in the live region); the stack expands while it is hovered or holds focus; Tab reaches each toast's Dismiss button, Enter or Space closes it, Escape also dismisses the focused toast.
 * Accessibility: toasts are announced politely through a live region (errors are announced too, never
 * stealing focus); they pause their timer while hovered or focused, so there is time to read; the Dismiss button
 * has a 44px hit area on touch screens.
 * Glass and motion: each toast is a `glass-2` surface (the viewport is fixed and clear of notches and home
 * indicators). Toasts slide in from their edge (from above at the top, from below at the bottom) and leave the
 * same way; exits are shorter, ease-in and never overshoot. The newest toast sits at the edge and older ones
 * peek out behind it, towards the middle of the screen; hovering or focusing the stack fans it out the same
 * way. With reduced motion (OS or in-app toggle) toasts only fade and the stack re-arranges without sliding.
 * Swiping still follows the finger: that is direct manipulation, not animation.
 *
 * @example
 * ```tsx
 * import { ToastProvider, Toaster, useToast } from "@sheenui/theme";
 *
 * function SaveButton() {
 *   const toast = useToast();
 *   return <button onClick={() => toast.success("Saved", "Your changes are live.")}>Save</button>;
 * }
 *
 * export function Example() {
 *   return (
 *     <ToastProvider>
 *       <SaveButton />
 *       <Toaster position="bottom-center" />
 *     </ToastProvider>
 *   );
 * }
 * ```
 *
 * @see /components/toast
 */
export function ToastProvider({
  viewportReady = true,
  onViewportNeeded,
  children,
  ...props
}: ComponentProps<typeof BaseToast.Provider> & {
  /**
   * Set to `false` while the `Toaster` is lazy-loaded: toasts raised meanwhile are held (their timer has not started)
   * and shown, in order, once this turns `true`, which is when the `Toaster` has mounted. Default `true`.
   * @default true
   */
  viewportReady?: boolean;
  /**
   * Called when a toast is held because the viewport is not ready, so the app can start loading the `Toaster`. Default
   * `undefined` (nothing is called).
   * @default undefined
   */
  onViewportNeeded?: () => void;
}) {
  const [gate] = useState(() => createToastGate(viewportReady));
  useEffect(() => {
    gate.sync(viewportReady, onViewportNeeded);
  }, [gate, viewportReady, onViewportNeeded]);
  return (
    <BaseToast.Provider {...props}>
      <ToastGateContext value={gate}>{children}</ToastGateContext>
    </BaseToast.Provider>
  );
}

/** Which icon and colour a toast uses. */
export type ToastType = "info" | "success" | "warning" | "danger" | "loading";

/** Corner or edge-centre of the screen where the stack sits. */
export type ToastPosition = "top-right" | "top-center" | "top-left" | "bottom-right" | "bottom-center" | "bottom-left";
/** What the `position` prop accepts: a physical {@link ToastPosition}, or `top-start` / `top-end` / `bottom-start` / `bottom-end`, which resolve against the text direction (`start` is the left corner in `ltr`, the right corner in `rtl`). */
export type ToastPositionProp = ToastPosition | "top-start" | "top-end" | "bottom-start" | "bottom-end";

/** Options of one toast: how long it stays, whether it has an action, where it sits. */
export type ToastOptions = {
  /** Use this id (to update or dismiss it later). A generated one is used by default. */
  id?: string;
  /**
   * How long it stays, in ms. `0` (or `persistent`) keeps it until it is dismissed. Default 5000, except a toast with an
   * `action`, which stays until dismissed (WCAG 2.2.1); an explicit duration on such a toast is raised to at least 20 000.
   */
  duration?: number;
  /** Keep it until the person (or your code) dismisses it. Same as `duration: 0`. */
  persistent?: boolean;
  /** A button on the toast, such as "Undo". */
  action?: { label: string; onClick: () => void };
  /** Show this toast in the `Toaster` with this position (see `ToasterProps.onlyPositioned`). Default: the main toaster. */
  position?: ToastPositionProp;
  /** "high" announces it assertively (use it for errors that need attention). Default "low" (polite). */
  priority?: "low" | "high";
  /** Called when the toast closes, however it closes. */
  onClose?: () => void;
};

/** What `toast.update(id, ...)` can change on a toast that is already showing. */
export type ToastUpdate = ToastOptions & { type?: ToastType; title?: ReactNode; description?: ReactNode };

/** The three states of `toast.promise(promise, messages)`: each a message, or a function of the result. */
export type ToastPromiseMessages<T> = {
  /** Shown while the promise is pending. */
  loading: ReactNode;
  /** Shown when it resolves: a message or `(result) => message`. */
  success: ReactNode | ((result: T) => ReactNode);
  /** Shown when it rejects: a message or `(error) => message`. */
  error: ReactNode | ((error: unknown) => ReactNode);
};

/**
 * `const toast = useToast()` returns the functions that show toasts. `toast.info`, `toast.success`, `toast.warning`,
 * `toast.error` and `toast.loading` each take `(title, description?, options?)` and return the toast's id;
 * `toast.promise(promise, { loading, success, error })` shows one toast that changes with the promise;
 * `toast.update(id, changes)` edits a showing toast; `toast.dismiss(id?)` closes one toast or all.
 * Options: `duration` (ms, `0` or `persistent` for a toast that stays), `action` (`{ label, onClick }`, such as Undo),
 * `position` (a per-toast spot, see `Toaster`'s `onlyPositioned`), `priority`, `id` and `onClose`.
 * Call it in any component below `ToastProvider`. Titles and descriptions are any React node.
 *
 * Accessibility: the title and description are announced by a polite live region. Keep them short and do
 * not put the only copy of important information in a toast. Glass and motion: see `ToastProvider`.
 *
 * @example
 * ```tsx
 * import { useToast } from "@sheenui/theme";
 *
 * export function Example() {
 *   const toast = useToast();
 *
 *   // Call the toast from an event handler (or an effect), never while rendering.
 *   async function save() {
 *     const id = toast.loading("Saving…");
 *     try {
 *       await fetch("/api/save", { method: "POST" });
 *       toast.update(id, { type: "success", title: "Saved", duration: 4000, action: { label: "Undo", onClick: () => undefined } });
 *     } catch {
 *       toast.update(id, { type: "danger", title: "Upload failed", description: "Check your connection and try again." });
 *     }
 *   }
 *
 *   return (
 *     <>
 *       <button onClick={() => void save()}>Save</button>
 *       <button onClick={() => void toast.promise(fetch("/api/sync"), { loading: "Syncing…", success: "Synced", error: "Could not sync" })}>Sync</button>
 *       <button onClick={() => toast.dismiss()}>Clear all</button>
 *     </>
 *   );
 * }
 * ```
 *
 * @see /components/toast
 */
export function useToast() {
  const { add: baseAdd, close: baseClose, update: baseUpdate, promise: basePromise } = BaseToast.useToastManager();
  const gate = useContext(ToastGateContext);
  // The functions the manager hands out are stable, so the API object is built once and keeps its identity:
  // `toast` is safe in effect dependency lists and does not re-render memoised children.
  return useMemo(() => {
    // Before the viewport is mounted a call is held (its timer must not run unseen) and the app is asked to load it.
    const held = (run: () => void) => {
      if (!gate || gate.isReady()) return false;
      gate.hold(run);
      gate.request();
      return true;
    };
    const addToast = (options: Parameters<typeof baseAdd>[0]) => {
      if (!gate || gate.isReady()) return baseAdd(options);
      // `add` returns its id at once, so a held toast gets its id up front.
      const id = options.id ?? gate.nextId();
      held(() => void baseAdd({ ...options, id }));
      return id;
    };
    const close = (id?: string) => {
      if (!held(() => baseClose(id))) baseClose(id);
    };
    const updateToast = (id: string, changes: Parameters<typeof baseUpdate>[1]) => {
      if (!held(() => baseUpdate(id, changes))) baseUpdate(id, changes);
    };
    const promiseToast = <T,>(promise: Promise<T>, options: Parameters<typeof basePromise<T>>[1]) => {
      if (!held(() => void basePromise(promise, options).catch(() => undefined))) return basePromise(promise, options);
      return promise;
    };
    const fields = (options: ToastOptions = {}) => ({
      ...(options.id !== undefined && { id: options.id }),
      // WCAG 2.2.1: a toast with an action (Undo) must not vanish before the person can reach it. It stays until
      // dismissed unless a duration is given, and a given one is never shorter than 20 s (timers also pause on hover/focus).
      ...(options.persistent === true
        ? { timeout: 0 }
        : options.duration !== undefined
          ? {
              timeout:
                options.duration === 0 || !options.action ? options.duration : Math.max(options.duration, 20_000),
            }
          : options.action
            ? { timeout: 0 }
            : {}),
      ...(options.priority !== undefined && { priority: options.priority }),
      ...(options.onClose !== undefined && { onClose: options.onClose }),
      ...(options.action && { actionProps: { children: options.action.label, onClick: options.action.onClick } }),
      ...(options.position !== undefined && { data: { position: options.position } }),
    });
    const add = (type: ToastType) => (title: ReactNode, description?: ReactNode, options?: ToastOptions) =>
      addToast({ title, description, type, ...(type === "loading" ? { timeout: 0 } : {}), ...fields(options) });
    // How long a settled promise toast stays: nothing for `persistent`, else the duration (default 5000 ms).
    const settledTimeout = (options?: ToastOptions) => (options?.persistent === true ? 0 : (options?.duration ?? 5000));
    return {
      info: add("info"),
      success: add("success"),
      warning: add("warning"),
      /** A danger toast ("error" is the method name people reach for; the type is "danger"). */
      error: add("danger"),
      /** A toast with a spinner that stays until you `update` or `dismiss` it. */
      loading: add("loading"),
      /** One toast that shows `loading`, then `success` or `error` when the promise settles. Returns the original promise (it still rejects when yours does, so `await` or `.catch` it). */
      promise: <T,>(promise: Promise<T>, messages: ToastPromiseMessages<T>, options?: ToastOptions) =>
        promiseToast(promise, {
          loading: { title: messages.loading, type: "loading", ...fields(options), timeout: 0 },
          success: (result: T) => ({
            title:
              typeof messages.success === "function"
                ? (messages.success as (r: T) => ReactNode)(result)
                : messages.success,
            type: "success",
            timeout: settledTimeout(options),
          }),
          error: (error: unknown) => ({
            title:
              typeof messages.error === "function"
                ? (messages.error as (e: unknown) => ReactNode)(error)
                : messages.error,
            type: "danger",
            timeout: settledTimeout(options),
          }),
        }),
      /** Change a toast that is showing: its type, title, description, duration or action. */
      update: (id: string, changes: ToastUpdate) => {
        const { type, title, description } = changes;
        updateToast(id, {
          ...(type !== undefined && { type }),
          ...(title !== undefined && { title }),
          ...(description !== undefined && { description }),
          ...fields(changes),
        });
      },
      /** Close one toast by id, or every toast when called without one. */
      dismiss: (id?: string) => close(id),
    };
  }, [gate, baseAdd, baseClose, baseUpdate, basePromise]);
}

/** Props of `Toaster`; each option is documented on its field. */
export type ToasterProps = {
  /**
   * Where the stack sits. Top positions slide in from above and stack downwards; bottom
   * positions slide up and stack upwards. On phones every position spans the screen width
   * (minus 16px gutters), so only top / bottom matters there. Default "top-right". `"top-left"` and the other `left` / `right`
   * names are physical; `"top-start"`, `"top-end"`, `"bottom-start"` and `"bottom-end"` follow the text direction
   * (`start` is the left corner in `ltr`, the right corner in `rtl`).
   */
  position?: ToastPositionProp;
  /** Extra classes for the viewport (the fixed element that holds the stack). */
  className?: string;
  /** Render the stack inside this element instead of the page: the viewport turns `absolute` and sits in the corner of the container (give it `position: relative`), so a demo or a panel can host its own toasts next to what triggers them. Default: the page (`document.body`, fixed to the screen). */
  container?: HTMLElement | null;
  /** Show only toasts that were given this `position` option (a second `Toaster` for per-toast positions). Default false: show toasts without a position. */
  onlyPositioned?: boolean;
  /** Visible-to-assistive-tech text of the toasts. Translate it here; `dismiss` is the accessible name of each toast's × button. */
  labels?: Partial<ToasterLabels>;
};

/** Every user-facing string of the toasts that is not the message itself. */
export type ToasterLabels = {
  /** Accessible name of the × button on each toast. */
  dismiss: string;
  /** Spoken name of the spinner on a "loading" toast. */
  loading: string;
  /** Accessible name of the notifications region. Give each stack on a page its own name. */
  region: string;
  /** Hidden text added to a toast that has an action, so the live region tells the keyboard route once: F6, then Tab. */
  actionHint: (action: string) => string;
};

/** English defaults of `ToasterLabels`. */
export const defaultToasterLabels: ToasterLabels = {
  dismiss: "Dismiss",
  loading: "Loading",
  region: "Toast notifications",
  actionHint: (action) => `Press F6, then Tab to reach ${action}.`,
};

export { Toaster } from "./toaster";

/** Props of {@link ToastProvider}. Glass toasts that stack, expand on hover and can be swiped away. */
export type ToastProviderProps = ComponentProps<typeof ToastProvider>;

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type PointerEvent,
  type ReactNode,
} from "react";
import { Toast as BaseToast } from "@base-ui/react/toast";

import { PHONE_QUERY, useMediaQuery } from "../hooks/use-media-query";
import { useResolvedDirection } from "../hooks/use-direction";
import { cn } from "../lib/cn";
import { duration } from "../motion/tokens";
import { StateLightLayer, type SheenLightState } from "../lib/state-light";
import { SpinnerIcon } from "../spinner/spinner";
import {
  defaultToasterLabels,
  type ToastPosition,
  type ToastPositionProp,
  type ToasterProps,
  type ToastType,
} from "./toast";

/*
 * The toast viewport and its list. Kept apart from toast.tsx (the provider and `useToast`) so an app
 * can load it after first paint: Base UI's toast root, swipe handling and viewport are ~9 KB gzip that
 * only matter once a toast is shown. `Toaster` is still exported from "./toast".
 */

/* Viewport: fixed to its corner, clear of notches and home indicators (safe-area insets).
   Phones: full width minus 16px gutters. From sm: a 360px column 32px from the edges. */
const viewportEdge = {
  top: "top-[max(1rem,env(safe-area-inset-top))] bottom-auto sm:top-[max(2rem,env(safe-area-inset-top))]",
  bottom: "top-auto bottom-[max(1rem,env(safe-area-inset-bottom))] sm:bottom-[max(2rem,env(safe-area-inset-bottom))]",
};
const viewportAlign = {
  right: "sm:right-[max(2rem,env(safe-area-inset-right))] sm:left-auto",
  left: "sm:right-auto sm:left-[max(2rem,env(safe-area-inset-left))]",
  // Equal insets + auto margins centre a fixed-width box without a transform.
  center: "sm:mx-auto",
};

/* Root, per edge. --toast-offset-y (from Base UI) is the summed height of the newer toasts
   in front; --toast-index counts from the front (0 = newest). */
const rootEdge = {
  top: cn(
    "top-0 origin-top",
    "[--offset-y:calc(var(--toast-offset-y)+(var(--toast-index)*var(--gap))+var(--toast-swipe-movement-y))]",
    // Collapsed: older toasts shrink and peek out BELOW the newest one.
    "[transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--toast-swipe-movement-y)+(var(--toast-index)*var(--peek))+(var(--shrink)*var(--height))))_scale(var(--scale))]",
    // Keeps the pointer "inside" the stack while it crosses the gaps of the fanned-out list.
    "before:bottom-full",
    "motion-ok:data-starting-style:[transform:translateY(-24px)_scale(0.96)]",
    "motion-ok:[&[data-ending-style]:not([data-limited]):not([data-behind]):not([data-swipe-direction])]:[transform:translateY(-150%)]",
  ),
  bottom: cn(
    "bottom-0 origin-bottom",
    "[--offset-y:calc(var(--toast-offset-y)*-1+(var(--toast-index)*var(--gap)*-1)+var(--toast-swipe-movement-y))]",
    // Collapsed: older toasts shrink and peek out ABOVE the newest one.
    "[transform:translateX(var(--toast-swipe-movement-x))_translateY(calc(var(--toast-swipe-movement-y)-(var(--toast-index)*var(--peek))-(var(--shrink)*var(--height))))_scale(var(--scale))]",
    "before:top-full",
    "motion-ok:data-starting-style:[transform:translateY(24px)_scale(0.96)]",
    "motion-ok:[&[data-ending-style]:not([data-limited]):not([data-behind]):not([data-swipe-direction])]:[transform:translateY(150%)]",
  ),
};

/** Swipe towards the nearest edges to dismiss: up (or down) plus the side the stack is on. */
/** Turns a logical `…-start` / `…-end` position into the physical corner for the text direction. */
function resolveToastPosition(position: ToastPositionProp, dir: "ltr" | "rtl"): ToastPosition {
  if (!position.endsWith("-start") && !position.endsWith("-end")) return position as ToastPosition;
  const [edge, logical] = position.split("-") as ["top" | "bottom", "start" | "end"];
  const left = (logical === "start") === (dir === "ltr");
  return `${edge}-${left ? "left" : "right"}`;
}

const swipeDirections: Record<ToastPosition, ("up" | "down" | "left" | "right")[]> = {
  "top-right": ["up", "right"],
  "top-left": ["up", "left"],
  "top-center": ["up", "left", "right"],
  "bottom-right": ["down", "right"],
  "bottom-left": ["down", "left"],
  "bottom-center": ["down", "left", "right"],
};

/*
 * Swipe velocity: the pointer's speed is sampled while it drags, and on release the exit duration becomes
 * (distance left) / (speed), clamped to 60 ms - duration.base (never longer than the entrance), so the toast leaves at the speed of the finger.
 * Base UI does the drag itself; this only sets one CSS variable.
 */
const swipeSamples = new WeakMap<Element, { x: number; y: number; t: number; v: number }>();
function trackSwipe(event: PointerEvent<HTMLElement>) {
  if (event.buttons === 0 && event.pointerType === "mouse") return;
  const el = event.currentTarget;
  const prev = swipeSamples.get(el);
  const now = event.timeStamp;
  if (prev && now > prev.t) {
    const v = Math.hypot(event.clientX - prev.x, event.clientY - prev.y) / (now - prev.t);
    swipeSamples.set(el, { x: event.clientX, y: event.clientY, t: now, v: prev.v * 0.5 + v * 0.5 });
  } else if (!prev) {
    swipeSamples.set(el, { x: event.clientX, y: event.clientY, t: now, v: 0 });
  }
}
function releaseSwipe(event: PointerEvent<HTMLElement>) {
  const el = event.currentTarget;
  const sample = swipeSamples.get(el);
  swipeSamples.delete(el);
  if (!sample || sample.v < 0.2 || event.timeStamp - sample.t > 80) {
    el.style.removeProperty("--sheen-swipe-dur");
    return;
  }
  // Distance still to cover: the exit ends 150% of the toast away along the swipe axis. Duration = distance /
  // measured speed, with no multiplier, so the toast leaves at the speed of the finger.
  const mx = Math.abs(parseFloat(el.style.getPropertyValue("--toast-swipe-movement-x")) || 0);
  const my = Math.abs(parseFloat(el.style.getPropertyValue("--toast-swipe-movement-y")) || 0);
  const horizontal = mx >= my;
  const remaining = Math.max(0, (horizontal ? el.offsetWidth : el.offsetHeight) * 1.5 - (horizontal ? mx : my));
  el.style.setProperty(
    "--sheen-swipe-dur",
    `${Math.round(Math.min(duration.base * 1000, Math.max(60, remaining / sample.v)))}ms`,
  );
}

/* On a phone the stack spans the screen, so a swipe to either side is the natural dismiss gesture. */
/**
 * The fixed viewport that renders the toast stack. Render exactly one inside `ToastProvider`.
 * `position` picks the corner or edge ("top-right" by default, "bottom-center", ...); `className` styles the viewport.
 * On phones every position spans the screen width (minus 16px gutters), so only top or bottom matters there.
 *
 * Keyboard: Tab reaches the toasts' Dismiss buttons while the stack is open; swipe towards the nearest edge to
 * dismiss on touch (on a phone, to either side). Accessibility: a live region announces new toasts; the viewport sits clear of safe-area insets.
 * Glass and motion: see `ToastProvider` (glass-2 toasts, slide-in, fan-out on hover, fade-only under reduced motion).
 *
 * @example
 * ```tsx
 * import { Toaster, ToastProvider } from "@sheenui/theme";
 *
 * // Placeholders for your own code:
 * declare const App: () => React.JSX.Element;
 *
 * export function Example() {
 *   return (
 *     <ToastProvider>
 *       <App />
 *       <Toaster position="bottom-right" />
 *     </ToastProvider>
 *   );
 * }
 * ```
 *
 * @see /components/toast
 */
export function Toaster({
  position: positionProp = "top-right",
  className,
  onlyPositioned = false,
  container,
  labels,
}: ToasterProps) {
  const dir = useResolvedDirection();
  const position = resolveToastPosition(positionProp, dir);
  const dismiss = labels?.dismiss ?? defaultToasterLabels.dismiss;
  const loadingLabel = labels?.loading ?? defaultToasterLabels.loading;
  const actionHint = labels?.actionHint ?? defaultToasterLabels.actionHint;
  const [edge, align] = position.split("-") as ["top" | "bottom", "left" | "center" | "right"];
  const phone = useMediaQuery(PHONE_QUERY);
  useRestoreFocusAfterToast();
  const swipe = phone
    ? [...new Set([...swipeDirections[position], "left" as const, "right" as const])]
    : swipeDirections[position];
  return (
    <BaseToast.Portal container={container ?? undefined}>
      <BaseToast.Viewport
        data-slot="toaster"
        aria-label={labels?.region ?? defaultToasterLabels.region}
        data-position={position}
        className={cn(
          "z-[60] sm:w-[22.5rem]",
          container ? "absolute" : "fixed",
          "right-[max(1rem,env(safe-area-inset-right))] left-[max(1rem,env(safe-area-inset-left))]",
          viewportEdge[edge],
          viewportAlign[align],
          className,
        )}
      >
        <ToastList
          edge={edge}
          swipeDirection={swipe}
          dismissLabel={dismiss}
          loadingLabel={loadingLabel}
          actionHint={actionHint}
          position={position}
          dir={dir}
          onlyPositioned={onlyPositioned}
        />
      </BaseToast.Viewport>
    </BaseToast.Portal>
  );
}

const icons: Record<Exclude<ToastType, "loading">, ReactNode> = {
  info: <path d="M12 16v-4m0-4h.01" />,
  success: <path d="M8 12.5l2.5 2.5L16 9.5" />,
  warning: <path d="M12 8v4m0 4h.01" />,
  danger: <path d="M12 8v4m0 4h.01" />,
};

/* The status light of each type: --glow feeds the soft wash behind the icon (the Content's background). Loading is accent. */
const glowColor: Record<ToastType, string> = {
  info: "[--glow:var(--sheen-accent-glow)]",
  success: "[--glow:var(--sheen-success-glow)]",
  warning: "[--glow:var(--sheen-warning-glow)]",
  danger: "[--glow:var(--sheen-danger-glow)]",
  loading: "[--glow:var(--sheen-accent-glow)]",
};

/** The state light of each toast type (`data-state` on the toast): info stays unlit; loading is working; danger is error. */
const lightState: Record<ToastType, SheenLightState> = {
  info: "idle",
  success: "success",
  warning: "warning",
  danger: "error",
  loading: "working",
};

const iconColor: Record<ToastType, string> = {
  info: "text-sheen-accent",
  success: "text-sheen-success-text",
  warning: "text-sheen-warning-text",
  danger: "text-sheen-danger-text",
  loading: "text-sheen-accent",
};

/*
 * F6 moves focus into the toast viewport (Base UI). Remember where it came from, and when Escape (or a dismiss)
 * leaves focus on nothing useful (the body or the viewport region), put it back on that element.
 */
function useRestoreFocusAfterToast() {
  const origin = useRef<HTMLElement | null>(null);
  useEffect(() => {
    const inToaster = (node: Element | null) => !!node?.closest("[data-slot=toaster],[data-slot=toast]");
    const onKeyDown = (event: KeyboardEvent) => {
      const active = document.activeElement;
      if (event.key === "F6" && active instanceof HTMLElement && !inToaster(active)) origin.current = active;
      if (event.key === "Escape" && inToaster(active)) {
        const target = origin.current;
        origin.current = null;
        if (target?.isConnected)
          // After Base UI has handled the key and dismissed the toast.
          setTimeout(() => {
            if (
              !document.activeElement ||
              document.activeElement === document.body ||
              inToaster(document.activeElement)
            )
              target.focus({ preventScroll: true });
          }, 0);
      }
    };
    document.addEventListener("keydown", onKeyDown, true);
    return () => document.removeEventListener("keydown", onKeyDown, true);
  }, []);
}

/* Base UI hides toast parts from assistive tech (aria-hidden): a high-priority toast until focus enters it (a live
 * region announces it instead), and every Close button while the stack is collapsed and unfocused. A focusable control
 * inside aria-hidden is an a11y violation, so such a button leaves the tab order, and returns as soon as aria-hidden
 * is lifted (the stack expands or takes focus). */
function useTabbableWhenShown() {
  const [tabIndex, setTabIndex] = useState<number | undefined>(undefined);
  const ref = useCallback((node: HTMLElement | null) => {
    if (!node) return undefined;
    const toast = node.closest("[data-slot=toast]");
    // Focus inside the toast (the toast itself included) keeps its buttons tabbable, so keyboard users can reach them
    // from the toast; they are only taken out of the tab order while nobody is in the toast and they are hidden.
    const sync = () =>
      setTabIndex(node.closest("[aria-hidden=true]") && !toast?.contains(document.activeElement) ? -1 : undefined);
    sync();
    toast?.addEventListener("focusin", sync);
    const onOut = () => queueMicrotask(sync);
    toast?.addEventListener("focusout", onOut);
    const observer = new MutationObserver(sync);
    const options = { attributes: true, attributeFilter: ["aria-hidden"] };
    // aria-hidden can sit on any ancestor up to the toast (Base UI puts it on the Content), so watch the whole chain.
    for (let el: HTMLElement | null = node; el; el = el === toast ? null : el.parentElement)
      observer.observe(el, options);
    return () => {
      observer.disconnect();
      toast?.removeEventListener("focusin", sync);
      toast?.removeEventListener("focusout", onOut);
    };
  }, []);
  return { ref, tabIndex };
}

function ToastAction(props: ComponentProps<typeof BaseToast.Action>) {
  const { ref, tabIndex } = useTabbableWhenShown();
  return <BaseToast.Action ref={ref} tabIndex={tabIndex} {...props} />;
}

function ToastDismiss(props: ComponentProps<typeof BaseToast.Close>) {
  const { ref, tabIndex } = useTabbableWhenShown();
  return <BaseToast.Close ref={ref} tabIndex={tabIndex} {...props} />;
}

function ToastList({
  edge,
  swipeDirection,
  dismissLabel,
  loadingLabel,
  actionHint,
  position,
  dir,
  onlyPositioned,
}: {
  edge: "top" | "bottom";
  swipeDirection: ("up" | "down" | "left" | "right")[];
  dismissLabel: string;
  loadingLabel: string;
  actionHint: (action: string) => string;
  position: ToastPosition;
  dir: "ltr" | "rtl";
  onlyPositioned: boolean;
}) {
  const { toasts } = BaseToast.useToastManager();
  const mine = toasts.filter((toast) => {
    const own = (toast.data as { position?: ToastPositionProp } | undefined)?.position;
    return own === undefined ? !onlyPositioned : resolveToastPosition(own, dir) === position;
  });

  return mine.map((toast) => {
    const type: ToastType =
      toast.type === "loading" || (toast.type as ToastType) in icons ? (toast.type as ToastType) : "info";
    return (
      <BaseToast.Root
        data-slot="toast"
        data-state={lightState[type]}
        key={toast.id}
        toast={toast}
        swipeDirection={swipeDirection}
        onPointerMove={trackSwipe}
        onPointerUp={releaseSwipe}
        className={cn(
          "glass-2 absolute right-0 left-0 w-full rounded-sheen-lg select-none",
          // Stacking: newer toasts sit in front, older ones peek out behind.
          "[--gap:0.75rem] [--peek:0.5rem] sm:[--peek:0.75rem] [--scale:calc(max(0,1-(var(--toast-index)*0.1)))] [--shrink:calc(1-var(--scale))]",
          "[--height:var(--toast-frontmost-height,var(--toast-height))]",
          "z-[calc(1000-var(--toast-index))] h-(--height) data-expanded:h-(--toast-height)",
          // The hover bridge lives in ::before: glass-2 paints its lit rim in ::after, which must keep the toast's own box.
          "before:absolute before:left-0 before:h-[calc(var(--gap)+1px)] before:w-full before:content-['']",
          rootEdge[edge],
          glowColor[type],
          // The state light (a lit edge and a faint aura; the wash behind the icon is the pool). Peeking layers stay unlit.
          "[&[data-behind]:not([data-expanded])>[data-slot=state-light]]:hidden",
          // Peeking layers (collapsed, behind the newest): only the lit hairline, no cast shadow, so stacked shadows
          // never pile into a dark smudge under the toast in front.
          "[&[data-behind]:not([data-expanded])]:[box-shadow:var(--sheen-glass-rim)]",
          // Expanded (hover / focus): the stack fans out away from its edge, one gap apart.
          "data-expanded:[transform:translateX(var(--toast-swipe-movement-x))_translateY(var(--offset-y))]",
          "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
          // Enter / exit: always a fade; the slide only when motion is welcome.
          "data-starting-style:opacity-0 data-ending-style:opacity-0 data-limited:opacity-0",
          "motion-ok:data-ending-style:data-[swipe-direction=down]:[transform:translateY(calc(var(--toast-swipe-movement-y)+150%))]",
          "motion-ok:data-ending-style:data-[swipe-direction=up]:[transform:translateY(calc(var(--toast-swipe-movement-y)-150%))]",
          "motion-ok:data-ending-style:data-[swipe-direction=right]:[transform:translateX(calc(var(--toast-swipe-movement-x)+150%))_translateY(var(--offset-y))]",
          "motion-ok:data-ending-style:data-[swipe-direction=left]:[transform:translateX(calc(var(--toast-swipe-movement-x)-150%))_translateY(var(--offset-y))]",
          // Reduced motion: opacity only, so stack changes jump instead of sliding. Height is never transitioned: a bottom-anchored toast that animates its height moves its top edge every frame (layout shift).
          "[transition:opacity_var(--sheen-duration-base)_var(--sheen-ease-out)]",
          // In and reflow on `smooth` (a settle without overshoot); the hover fan-out is snappier.
          "motion-ok:[transition:transform_var(--sheen-duration-smooth)_var(--sheen-ease-smooth),opacity_var(--sheen-duration-base)_var(--sheen-ease-out)]",
          "motion-ok:data-expanded:[transition:transform_var(--sheen-duration-snappy)_var(--sheen-ease-snappy),opacity_var(--sheen-duration-base)_var(--sheen-ease-out)]",
          // Exits: shorter, ease-in, never overshoot (incl. swipe-away). Reduced motion: fade only.
          "data-ending-style:[transition:opacity_var(--sheen-duration-exit)_var(--sheen-ease-exit)]",
          "motion-ok:data-ending-style:[transition:transform_var(--sheen-duration-exit)_var(--sheen-ease-exit),opacity_var(--sheen-duration-exit)_var(--sheen-ease-exit)]",
          // A swipe leaves at the finger's release speed (--sheen-swipe-dur, set on pointer up, at most duration.base), with ease.exit.
          "motion-ok:data-ending-style:data-swipe-direction:[transition:transform_var(--sheen-swipe-dur,var(--sheen-duration-exit))_var(--sheen-ease-exit),opacity_var(--sheen-swipe-dur,var(--sheen-duration-exit))_var(--sheen-ease-exit)]",
        )}
      >
        <StateLightLayer className="[--sl-pool:0] [--sl-aura:0.55] [--sl-strength:0.85]" />
        <BaseToast.Content className="flex items-start gap-3 overflow-hidden rounded-[inherit] bg-[radial-gradient(circle_at_1.75rem_1.5rem,color-mix(in_oklab,var(--glow)_50%,transparent),transparent_10rem)] p-3.5 sm:p-4 transition-opacity duration-(--sheen-duration-instant) ease-sheen-exit data-behind:opacity-0 data-behind:duration-0 data-expanded:opacity-100 data-expanded:delay-75 data-expanded:duration-(--sheen-duration-base) data-expanded:ease-sheen-out">
          <span className={cn("mt-0.5 flex size-5 shrink-0 items-center justify-center", iconColor[type])}>
            {type === "loading" ? (
              <span className="flex">
                <SpinnerIcon className="size-5" strokeWidth={2.4} />
                <span className="sr-only">{loadingLabel}</span>
              </span>
            ) : (
              <svg
                aria-hidden
                viewBox="0 0 24 24"
                className="size-5"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              >
                <circle cx="12" cy="12" r="9" />
                {icons[type]}
              </svg>
            )}
          </span>
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            {/* A div, not Base UI's default h2: toasts sit before <main> and would start the page outline with h2s. */}
            <BaseToast.Title render={<div />} className="text-sm font-semibold text-sheen-fg" />
            <BaseToast.Description className="text-sm text-sheen-fg-muted" />
            {typeof toast.actionProps?.children === "string" && (
              <span className="sr-only">{actionHint(toast.actionProps.children)}</span>
            )}
            <ToastAction
              className={cn(
                "mt-2 inline-flex min-h-8 w-fit cursor-pointer items-center rounded-sheen-sm px-2.5 text-xs font-semibold text-sheen-accent",
                "border border-sheen-control-border transition-[color,background-color] duration-(--sheen-duration-fast) hover:bg-sheen-hover",
                "focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-sheen-focus any-pointer-coarse:min-h-11",
              )}
            />
          </div>
          <ToastDismiss
            aria-label={dismissLabel}
            className={cn(
              "relative flex size-6 shrink-0 items-center justify-center rounded-sheen-full text-sheen-fg-muted",
              "transition-[color,background-color] duration-(--sheen-duration-fast) hover:bg-sheen-hover hover:text-sheen-fg",
              "focus-visible:outline-2 focus-visible:outline-offset-0 focus-visible:outline-sheen-focus",
              // 44×44 on touch screens; negative margins keep the layout unchanged.
              "any-pointer-coarse:-my-2.5 any-pointer-coarse:-me-2.5 any-pointer-coarse:size-11",
            )}
          >
            <svg
              aria-hidden
              viewBox="0 0 24 24"
              className="size-3.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="2.2"
              strokeLinecap="round"
            >
              <path d="M6 6l12 12M18 6L6 18" />
            </svg>
          </ToastDismiss>
        </BaseToast.Content>
      </BaseToast.Root>
    );
  });
}

